    public static Category? GetCategory(string slug) => Categories().FirstOrDefault(c => c.Slug == slug);
    public static Product? GetProduct(string slug) => Products().FirstOrDefault(p => p.Slug == slug);
    public static IEnumerable<Product> CategoryProducts(string slug) => Products().Where(p => p.CategorySlug == slug);
    public static List<ProductCard> RelatedCards(Product p)
    {
        var all = Products();
        var related = all.Where(x => p.RelatedSlugs.Contains(x.Slug)).ToList();
        if (related.Count < 4)
        {
            var seen = new HashSet<string>(related.Select(r => r.Slug)) { p.Slug };
            related.AddRange(all
                .Where(x => seen.Add(x.Slug))
                .OrderByDescending(x => x.CategorySlug == p.CategorySlug));
        }
        return related.Take(4).Select(ToCard).ToList();
    }
    public static ProductCard ToCard(Product p) => new(p.Title, p.Slug, p.Image, p.BasePrice, $"{p.Title} - دوخت سفارشی مزون نارشا");

